const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: 'F(x)=F0(1−x/h)' },
      { kind: 'text', payload: 'x' },
      { kind: 'text', payload: 'F(x)' },
      { kind: 'text', payload: 'h' },
      { kind: 'text', payload: 'h/2' },
      { kind: 'text', payload: 'F0' },
      { kind: 'text', payload: 'F0/2' },
      { kind: 'text', payload: 'W/(F0h)=3/8=0.375' },
      { kind: 'text', payload: '0≤x≤h' },
      { kind: 'text', payload: '阴影面积 W' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = W * 0.12;
    var x1 = W * 0.92;
    var yBase = H * 0.80;
    var yTop = H * 0.14;
    var plotW = x1 - x0;
    var plotH = yBase - yTop;
    var xHalf = x0 + plotW * 0.5;
    var yHalf = yBase - plotH * 0.5;
    var lw = Math.max(1.5, Math.min(W, H) * 0.003);
    var color = '#26354a';
    var shadeColor = '#5b8fd480';
    var dotR = Math.max(3, Math.min(W, H) * 0.006);

    var xAxis = visualSdk.arrow(x0, yBase, x1 + W * 0.025, yBase, {});
    var yAxis = visualSdk.arrow(x0, yBase, x0, yTop - H * 0.025, {});
    var curve = visualSdk.polyline([[x0, yTop], [x1, yBase]]);

    var shade = [
      ['M', x0, yBase],
      ['L', xHalf, yBase],
      ['L', xHalf, yHalf],
      ['L', x0, yTop],
      ['Z']
    ];

    var guide = [
      ['M', xHalf, yBase],
      ['L', xHalf, yHalf]
    ];

    var ticks = [
      ['M', x0, yBase - H * 0.012], ['L', x0, yBase + H * 0.012],
      ['M', xHalf, yBase - H * 0.01], ['L', xHalf, yBase + H * 0.01],
      ['M', x1, yBase - H * 0.012], ['L', x1, yBase + H * 0.012],
      ['M', x0 - W * 0.01, yTop], ['L', x0 + W * 0.01, yTop],
      ['M', x0 - W * 0.01, yHalf], ['L', x0 + W * 0.01, yHalf]
    ];

    var dot = visualSdk.circle(xHalf, yHalf, dotR);

    return {
      schemaVersion: 1,
      sceneId: 'f-x-linear-area',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'xaxis', commands: xAxis },
        { id: 'yaxis', commands: yAxis },
        { id: 'shade', commands: shade },
        { id: 'guide', commands: guide },
        { id: 'curve', commands: curve },
        { id: 'ticks', commands: ticks },
        { id: 'dot', commands: dot }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'shade', fill: shadeColor },
          { type: 'path', pathId: 'guide', fill: color, stroke: { width: lw * 0.7, dash: [5, 5] } },
          { type: 'path', pathId: 'xaxis', fill: color, stroke: { width: lw } },
          { type: 'path', pathId: 'yaxis', fill: color, stroke: { width: lw } },
          { type: 'path', pathId: 'curve', fill: color, stroke: { width: lw * 1.3 } },
          { type: 'path', pathId: 'ticks', fill: color, stroke: { width: lw } },
          { type: 'path', pathId: 'dot', fill: color },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: x1, y: yTop - H * 0.035 }, hAlign: 'right', vAlign: 'bottom', color: color },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: x1 + W * 0.028, y: yBase + H * 0.018 }, hAlign: 'left', vAlign: 'top', color: color },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: x0, y: yTop - H * 0.065 }, hAlign: 'center', vAlign: 'bottom', color: color },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: x1, y: yBase + H * 0.018 }, hAlign: 'center', vAlign: 'top', color: color },
          { type: 'label', contentId: metrics[4].contentId, anchor: { x: xHalf, y: yBase + H * 0.018 }, hAlign: 'center', vAlign: 'top', color: color },
          { type: 'label', contentId: metrics[5].contentId, anchor: { x: x0 - W * 0.018, y: yTop }, hAlign: 'right', vAlign: 'middle', color: color },
          { type: 'label', contentId: metrics[6].contentId, anchor: { x: x0 - W * 0.018, y: yHalf }, hAlign: 'right', vAlign: 'middle', color: color },
          { type: 'label', contentId: metrics[7].contentId, anchor: { x: x0 + W * 0.035, y: yTop + H * 0.075 }, hAlign: 'left', vAlign: 'bottom', color: color },
          { type: 'label', contentId: metrics[8].contentId, anchor: { x: x0 + plotW * 0.5, y: yBase + H * 0.075 }, hAlign: 'center', vAlign: 'top', color: color },
          { type: 'label', contentId: metrics[9].contentId, anchor: { x: x0 + W * 0.02, y: yTop + H * 0.15 }, hAlign: 'left', vAlign: 'top', color: color }
        ]
      }
    };
  }
};
